import 'dotenv/config';
import express from 'express';
import cors from 'cors';
import jwt from 'jsonwebtoken';
import { createServer } from 'node:http';
import { Server } from 'socket.io';
import cron from 'node-cron';
import { db } from './db.js';
import { notifyTelegram, sendTelegramDocument } from './telegram.js';
import { buildOrderWorkbook } from './reports.js';

const app = express(); const http = createServer(app);
const io = new Server(http, { cors: { origin: '*' } });
app.use(cors()); app.use(express.json()); app.use('/r', express.static('../web-menu'));
app.get('/r/:slug/menu', (_, res) => res.sendFile('index.html', { root: '../web-menu' }));
const secret = process.env.JWT_SECRET || 'development-only-change-me';
const findRestaurant = slug => db.prepare('SELECT * FROM restaurants WHERE slug=?').get(slug);
const auth = (req,res,next) => { try { req.user=jwt.verify((req.headers.authorization||'').replace('Bearer ',''), secret); next(); } catch { res.status(401).json({error:'Admin kirishi talab qilinadi'}); } };
const tableState = id => { const order=db.prepare("SELECT status FROM orders WHERE table_id=? AND status IN ('new','seen','accepted') ORDER BY id DESC LIMIT 1").get(id); return order?.status || 'idle'; };
const localDate = timezone => { const parts=new Intl.DateTimeFormat('en-US', {timeZone: timezone, year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()); const value=type=>parts.find(x=>x.type===type).value; return `${value('year')}-${value('month')}-${value('day')}`; };
const scheduledRange = timezone => { const today=localDate(timezone); if(process.env.REPORT_PERIOD!=='monthly') return {from:today,to:today,label:'kunlik'}; const [y,m]=today.split('-').map(Number); const d=new Date(Date.UTC(y,m-2,1)); return {from:d.toISOString().slice(0,10),to:new Date(Date.UTC(y,m-1,0)).toISOString().slice(0,10),label:'oylik'}; };

io.on('connection', socket => socket.on('restaurant:join', slug => socket.join(`restaurant:${slug}`)));
app.get('/health', (_,res) => res.json({ok:true}));
app.get('/api/restaurants/:slug/menu', (req,res) => { const r=findRestaurant(req.params.slug); if(!r) return res.sendStatus(404); res.json({restaurant:r, tables:db.prepare('SELECT id,number FROM tables WHERE restaurant_id=? AND active=1 ORDER BY sort_order').all(r.id), items:db.prepare('SELECT id,name,price,category FROM menu_items WHERE restaurant_id=? AND active=1 ORDER BY category,sort_order').all(r.id)}); });
app.get('/api/orders/:id', (req,res) => { const order=db.prepare('SELECT * FROM orders WHERE id=?').get(req.params.id); if(!order) return res.sendStatus(404); res.json({...order,items:db.prepare('SELECT name,price,quantity FROM order_items WHERE order_id=?').all(order.id)}); });
app.post('/api/restaurants/:slug/orders', async (req,res) => { const r=findRestaurant(req.params.slug); const {tableId,items,note=''}=req.body; if(!r || !Array.isArray(items)||!items.length) return res.status(400).json({error:'Buyurtma ma’lumoti noto‘g‘ri'}); const table=db.prepare('SELECT * FROM tables WHERE id=? AND restaurant_id=? AND active=1').get(tableId,r.id); if(!table) return res.status(400).json({error:'Stol topilmadi'}); const create=db.transaction(() => { const result=db.prepare('INSERT INTO orders (restaurant_id,table_id,customer_note) VALUES (?,?,?)').run(r.id,table.id,note.slice(0,500)); const add=db.prepare('INSERT INTO order_items (order_id,menu_item_id,name,price,quantity) VALUES (?,?,?,?,?)'); for(const row of items) { const m=db.prepare('SELECT * FROM menu_items WHERE id=? AND restaurant_id=? AND active=1').get(row.menuItemId,r.id); if(!m || !Number.isInteger(row.quantity) || row.quantity<1 || row.quantity>50) throw new Error('Noto‘g‘ri mahsulot'); add.run(result.lastInsertRowid,m.id,m.name,m.price,row.quantity); } return result.lastInsertRowid; }); try { const id=create(); const order=db.prepare('SELECT * FROM orders WHERE id=?').get(id); const orderItems=db.prepare('SELECT * FROM order_items WHERE order_id=?').all(id); io.to(`restaurant:${r.slug}`).emit('order:new',{tableId:table.id,status:'new',orderId:id}); notifyTelegram(`<b>🔔 YANGI BUYURTMA</b>\n🏠 ${r.name}\n🪑 Stol: ${table.number}\n\n${orderItems.map(i=>`${i.quantity} × ${i.name}`).join('\n')}\n\n💰 ${orderItems.reduce((s,i)=>s+i.price*i.quantity,0).toLocaleString('uz-UZ')} so‘m`).catch(console.error); res.status(201).json({id,status:order.status}); } catch(e) {res.status(400).json({error:e.message});} });
app.post('/api/auth/pin',(req,res)=>{ const {slug,pin}=req.body; const r=findRestaurant(slug); const admin=r&&db.prepare('SELECT * FROM admins WHERE restaurant_id=? AND pin_hash=?').get(r.id,String(pin)); if(!admin) return res.status(401).json({error:'PIN noto‘g‘ri'}); res.json({token:jwt.sign({restaurantId:r.id,adminId:admin.id,role:admin.role},secret,{expiresIn:'12h'})}); });
app.get('/api/restaurants/:slug/tables',(req,res)=>{const r=findRestaurant(req.params.slug);if(!r)return res.sendStatus(404);res.json(db.prepare('SELECT * FROM tables WHERE restaurant_id=? AND active=1 ORDER BY sort_order').all(r.id).map(t=>({...t,status:tableState(t.id)})));});
app.get('/api/tables/:id/orders/active',auth,(req,res)=>{const orders=db.prepare("SELECT * FROM orders WHERE table_id=? AND status IN ('new','seen','accepted') ORDER BY created_at").all(req.params.id);res.json(orders.map(o=>({...o,items:db.prepare('SELECT name,price,quantity FROM order_items WHERE order_id=?').all(o.id)})));});
app.post('/api/orders/:id/seen',auth,(req,res)=>{const o=db.prepare("SELECT o.*,r.slug FROM orders o JOIN restaurants r ON r.id=o.restaurant_id WHERE o.id=?").get(req.params.id);if(!o)return res.sendStatus(404); if(o.restaurant_id!==req.user.restaurantId)return res.sendStatus(403);db.prepare("UPDATE orders SET status='seen',seen_at=CURRENT_TIMESTAMP WHERE id=? AND status='new'").run(o.id);io.to(`restaurant:${o.slug}`).emit('order:seen',{orderId:o.id,tableId:o.table_id,status:'seen'});res.json({ok:true,status:'seen'});});
app.get('/api/admin/reports/orders.xlsx',auth,async(req,res)=>{const today=localDate(process.env.REPORT_TIMEZONE||'Asia/Tashkent');const from=String(req.query.from||today),to=String(req.query.to||from);if(!/^\d{4}-\d{2}-\d{2}$/.test(from)||!/^\d{4}-\d{2}-\d{2}$/.test(to))return res.status(400).json({error:'Sana YYYY-MM-DD formatida bo‘lsin'});const restaurant=db.prepare('SELECT * FROM restaurants WHERE id=?').get(req.user.restaurantId);const report=await buildOrderWorkbook(restaurant.name,restaurant.id,from,to);res.set({'Content-Type':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','Content-Disposition':`attachment; filename="buyurtmalar-${from}-${to}.xlsx"`});res.send(Buffer.from(report.buffer));});
app.post('/api/admin/tables',auth,(req,res)=>{const number=Number(req.body.number);if(!Number.isInteger(number)||number<1)return res.status(400).json({error:'Stol raqami noto‘g‘ri'});try{const max=db.prepare('SELECT COALESCE(MAX(sort_order),0) x FROM tables WHERE restaurant_id=?').get(req.user.restaurantId).x;const x=db.prepare('INSERT INTO tables (restaurant_id,number,sort_order) VALUES (?,?,?)').run(req.user.restaurantId,number,max+1);res.status(201).json({id:x.lastInsertRowid});}catch{res.status(409).json({error:'Bu stol mavjud'});}});
app.patch('/api/admin/tables/:id',auth,(req,res)=>{const t=db.prepare('SELECT * FROM tables WHERE id=? AND restaurant_id=?').get(req.params.id,req.user.restaurantId);if(!t)return res.sendStatus(404);const sort=Number(req.body.sortOrder);if(!Number.isInteger(sort)||sort<1)return res.status(400).json({error:'sortOrder talab qilinadi'});db.prepare('UPDATE tables SET sort_order=? WHERE id=?').run(sort,t.id);res.json({ok:true});});
const reportCron = process.env.REPORT_CRON;
if (reportCron) cron.schedule(reportCron, async () => { try { const range=scheduledRange(process.env.REPORT_TIMEZONE||'Asia/Tashkent'); for (const restaurant of db.prepare('SELECT * FROM restaurants').all()) { const report=await buildOrderWorkbook(restaurant.name,restaurant.id,range.from,range.to); await sendTelegramDocument(report.buffer,`buyurtmalar-${restaurant.slug}-${range.from}-${range.to}.xlsx`,`${restaurant.name}: ${range.label} hisobot (${range.from} — ${range.to}, ${report.count} buyurtma)`); } } catch (e) { console.error('Scheduled report failed:', e); } }, { timezone: process.env.REPORT_TIMEZONE || 'Asia/Tashkent' });
http.listen(process.env.PORT||3000,()=>console.log(`Lagan API ready on ${process.env.PORT||3000}`));
